const giftForm=document.querySelector('#give-form');
if(giftForm){const amount=giftForm.elements.amount;const frequency=()=>giftForm.elements.frequency.value;const status=document.querySelector('#gift-status');const button=document.querySelector('#give-button');let timer;const format=()=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(Number(amount.value)||0);const update=()=>{clearTimeout(timer);button.disabled=false;button.firstChild.textContent=`Review ${format()} ${frequency()==='monthly'?'monthly ':''}gift `;for(const b of giftForm.querySelectorAll('[data-amount]'))b.setAttribute('aria-pressed',String(Number(b.dataset.amount)===Number(amount.value)));status.textContent=''};giftForm.querySelectorAll('[data-amount]').forEach(b=>b.addEventListener('click',()=>{amount.value=b.dataset.amount;update()}));giftForm.addEventListener('input',update);giftForm.addEventListener('change',update);giftForm.addEventListener('submit',e=>{e.preventDefault();if(!giftForm.reportValidity())return;status.textContent=`You chose ${format()} ${frequency()==='monthly'?'monthly':'one time'} for ${giftForm.elements.designation.value}. Online payments are not connected. No charge has been made. Call (402) 870-8800 to discuss your gift.`});
const state=new URLSearchParams(location.search).get('preview');if(state){const banner=document.createElement('p');banner.className='policy-note';banner.textContent='Giving flow design preview. No payment is processed.';giftForm.prepend(banner);if(state==='monthly'){giftForm.elements.frequency.value='monthly';update()}if(state==='processing'){button.disabled=true;status.textContent='Preview: preparing checkout…';timer=setTimeout(()=>{button.disabled=false;status.textContent='Preview complete. In the connected site, this would open Stripe Checkout. No charge has been made.'},3500)}if(state==='failed'){status.textContent='Preview: the payment could not be completed. No gift was recorded. Review the amount and try again when payments are connected.'}if(state==='success'){status.textContent='Preview: this is where a verified gift confirmation will appear. No payment has been made.';const a=document.createElement('a');a.href='/thank-you/';a.className='text-link';a.textContent='Preview the thank-you page';status.append(document.createElement('br'),a)}}}
document.querySelectorAll('.draft-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const fields=[...new FormData(form)].map(([key,value])=>`${key}: ${value}`).join('\n\n');const blob=new Blob([`${form.dataset.kind} · The Tree of LIF\n\n${fields}\n\nThis message has not been sent. Call +1 (402) 870-8800 to arrange sharing.\n`],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tree-of-lif-message.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);form.querySelector('[role=status]').textContent='Your message download is ready. It has not been sent. Call (402) 870-8800 to arrange how to share it.'}));
